namespace F1Manager {
public static class Program {
[STAThread]public static void Main(string[] args){try{if(args.Contains("--self-test")){SelfTest.Run(args.Length>1?args[1]:Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"self-test.txt"));return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var form=new ManagerForm(args.Contains("--ui-test"));if(args.Contains("--ui-test")){string dir=args.Length>1?args[1]:Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Previews");form.Shown+=(o,e)=>form.BeginInvoke(new Action(()=>UITests.Run(form,dir)));}Application.Run(form);}catch(Exception ex){Environment.ExitCode=1;string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"crash.log");try{File.WriteAllText(path,ex.ToString());}catch{}if(!args.Contains("--self-test")&&!args.Contains("--ui-test"))MessageBox.Show("Не удалось запустить F1 Manager.\n"+ex.Message+"\nПодробности: "+path,"F1 Manager");}}

}
public static class SelfTest {
static int checks;static List<string> report=new List<string>();static void Check(bool ok,string text){checks++;if(!ok)throw new Exception("FAILED: "+text);report.Add("PASS "+text);}
static void Throws(Action a,string text){bool yes=false;try{a();}catch{yes=true;}Check(yes,text);}
public static void FinishSession(Career s){Engine.SimulateSession(s);}
static void FullSeason(Career s){while(!s.SeasonDone)FinishSession(s);Engine.Validate(s);}
static void FillPlayer(Career s){for(int kind=0;kind<=5;kind++)for(int seat=0;seat<(kind==0||kind==5?2:1);seat++){int k=kind,st=seat;var existing=s.People.FirstOrDefault(p=>p.Kind==k&&!p.Retired&&p.Deal!=null&&p.Deal.Team==s.Player&&p.Deal.Seat==st&&p.Deal.Until>=s.Year);if(existing!=null)continue;var recruit=s.People.Where(x=>x.Kind==k&&x.Deal==null&&!x.Retired&&(x.RetireYear==0||x.RetireYear>=s.Year)&&!s.Bookings.Any(b=>b.Person==x.Id)&&(k!=0||x.Rating<94&&x.Titles<2)).OrderByDescending(x=>x.Rating).FirstOrDefault()??Engine.Generate(s,k);var q=Engine.Negotiate(s,recruit,s.Year,seat);Engine.Sign(s,recruit.Id,s.Year,seat,q.Salary,1,q.MinSeverance,recruit.Kind==0&&(recruit.Rating>=94||recruit.Titles>=2)?"Первый пилот":"Равный статус");}}
