var risk=Data.Create(0,"",321);var rt=Engine.Team(risk,0);var low=Engine.Estimate(risk,Data.Parts[2],3).Failure;rt.Facilities[1].Level=5;Engine.Staff(risk,0,3).Rating=99;Engine.Staff(risk,0,4).Rating=99;Check(Engine.Estimate(risk,Data.Parts[2],3).Failure<low,"facilities and staff quality reduce failure probability");Engine.FacilityUpgrade(risk,3);int due=rt.Facilities[3].Due;Engine.Advance(risk,due);Check(Engine.Capacity(rt)==12&&rt.Facilities[3].Level==2,"engineering department increases engineer capacity after construction");
