var live=Data.Create(0,"",99);Engine.Start(live);Engine.Tick(live,10);Check(live.Weekend.Live.Elapsed>=9.9&&live.Weekend.Live.Entries.All(e=>e.Lap==0),"underlying lap engine preserves simulated seconds");Engine.Tick(live,240);Check(live.Weekend.Live.Entries.Any(e=>e.Lap>0&&e.Best<99999),"lap times generated as cars complete laps");Check(live.Weekend.Live.Entries.Any(e=>e.TyreWear>0&&e.TyreWear<100),"practice tyre wear has fractional progression");var reloaded=Engine.Deserialize(Engine.Serialize(live));Check(reloaded.Weekend.Live.Elapsed==live.Weekend.Live.Elapsed&&reloaded.Weekend.Live.Entries[0].Lap==live.Weekend.Live.Entries[0].Lap,"active session survives save/load");live.Weekend.Live.WeatherAt=live.Weekend.Live.Elapsed+.1;Check(Engine.Tick(live,1)&&live.Weekend.Live.AwaitingEvent&&live.Weekend.Live.Event.Contains("ПОГОДЫ"),"weather change emits an event for the session log");
live.Weekend.Live.SafetyUntil=live.Weekend.Live.Elapsed+.1;Check(Engine.Tick(live,1)&&live.Weekend.Live.Event.Contains("возобновляется"),"safety car restart emits an event for the session log");var race=Data.Create(-1,"Race",491);for(int i=0;i<6;i++)FinishSession(race);Check(race.Stage==6&&race.Weekend.Qual.Count==24,"Q1/Q2/Q3 form complete 24-car grid");Engine.Start(race);int driver=Engine.Drivers(race,race.Player).First().Id;Engine.Pit(race,driver,"H");Engine.Tick(race,120);Check(race.Weekend.Live.Entries.First(e=>e.Id==driver).Stops>=1,"manual pit command executes at end of lap");FinishSession(race);Check(race.Round==1&&race.Archive[0].Sessions.Last().Rows.Count==24,"full race archived with every driver");Check(race.Archive[0].Sessions.Last().Rows.Sum(r=>r.Points)<=101,"race points allocation valid with DNFs");
EngineeringTests.Run(Check,Throws);ResearchTests.Run(Check,Throws);Patch242Tests.Run(Check,Throws);Patch25Tests.Run(Check,Throws);Patch251Tests.Run(Check);Patch252Tests.Run(Check,Throws);Patch26Tests.Run(Check,Throws);
