for(int i=1;i<6;i++)Engine.SimulateSession(instant);var duo=Engine.Drivers(instant,0).OrderBy(p=>p.Deal.Seat).ToArray();Engine.SetPlan(instant,duo[0].Id,new Plan{Mode=0,Stops=new List<int>{20},Tyres=new List<string>{"M","H"}});Engine.SetPlan(instant,duo[1].Id,new Plan{Mode=1,Stops=new List<int>{15,35},Tyres=new List<string>{"S","M","H"}});var plansRoundTrip=Engine.Deserialize(Engine.Serialize(instant));Check(plansRoundTrip.Plans[duo[0].Id.ToString()].Stops.Count==1&&plansRoundTrip.Plans[duo[1].Id.ToString()].Stops.Count==2,"different strategies for both drivers survive save/load");
Throws(()=>Engine.SetPlan(instant,duo[0].Id,new Plan{Stops=new List<int>{30,10},Tyres=new List<string>{"S","M","H"}}),"unordered pit laps rejected");Throws(()=>Engine.SetPlan(instant,duo[0].Id,new Plan{Stops=new List<int>{20},Tyres=new List<string>{"M","M"}}),"single-compound dry Grand Prix rejected");Throws(()=>Engine.SetPlan(instant,duo[0].Id,new Plan{Stops=new List<int>{20},Tyres=new List<string>{"M","X"}}),"unknown tyre compound rejected");
instant.Weekend.Weather="Сухо";Engine.Start(instant);instant.Weekend.Live.WeatherAt=double.MaxValue;var raceLive=instant.Weekend.Live;Engine.SimulateSession(instant);Check(raceLive.Entries.Single(e=>e.Id==duo[0].Id).ScheduledStops==1&&raceLive.Entries.Single(e=>e.Id==duo[1].Id).ScheduledStops==2,"instant race executes each driver's selected pit schedule");Check(instant.Round==1&&instant.Archive.Count==1&&instant.Archive[0].Sessions.Last().Rows.Count==22,"instant race advances round and archives all results");
var sprint=Data.Create(0,"",938);sprint.Round=1;sprint.Stage=4;Engine.PrepareWeekend(sprint);Engine.SetPlan(sprint,0,new Plan{Mode=2,Tyres=new List<string>{"S"}});Engine.Start(sprint);Check(sprint.Weekend.Live.TargetLaps==19&&sprint.Weekend.Live.Entries.Single(e=>e.Id==0).Tyre=="S","sprint uses its own distance and selected starting tyre");sprint.Weekend.Live.WeatherAt=double.MaxValue;Engine.SimulateSession(sprint);Check(sprint.Plans.Count==0,"sprint plans do not leak into the Grand Prix");
var rain=Data.Create(0,"",948);rain.Stage=6;Engine.PrepareWeekend(rain);rain.Weekend.Weather="Сухо";Engine.Start(rain);rain.Weekend.Live.WeatherAt=.1;var changing=rain.Weekend.Live;Engine.Tick(rain,300,true);Check(changing.Weather=="Дождь","instant weather change is simulated");while(changing.Elapsed<300&&!changing.Finished)Engine.Tick(rain,30,true);Check(changing.Entries.Where(e=>e.Team==0&&!e.Dnf).All(e=>e.Tyre=="I"||e.Tyre=="W"),"engineer automatically changes player tyres after rain begins");Engine.SimulateSession(rain);Check(changing.Finished,"weather and safety events do not block instant completion");
var legacy=Data.Create(0,"",955);Engine.Start(legacy);legacy.Weekend.Live.Entries[0].Stops=2;legacy.Version=2;var migrated=Engine.Deserialize(Engine.Serialize(legacy));Check(migrated.Version==8&&migrated.Weekend.Live.Entries[0].ScheduledStops==2,"version 2 active saves migrate planned pit counters");Engine.SimulateSession(migrated);Check(migrated.Stage==1,"old paused session can be completed instantly");
foreach(var d in Data.Create(0,"",1).People.Where(p=>p.Kind==0&&p.Id<22)){using(var img=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("driver"+d.Id))Check(img!=null&&img.Length>1000,"embedded portrait for "+d.Name);}
FullSeason(contract);Check(contract.Hall.Count==1&&contract.Archive.Count==23,"full season completes and hall of fame records champions");Check(contract.Archive.Count(h=>h.Sessions.Any(r=>r.Name=="Спринт"))==6,"six complete sprint weekends");Engine.NextSeason(contract);Check(Engine.Staff(contract,contract.Player,4).Id==candidate.Id&&contract.Bookings.Count==0,"future staff booking activates at season rollover");Check(contract.Preseason&&contract.Round==0&&contract.Year==2027,"second season resets schedule and opens preseason");
